window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0cd8aa4a1129e7d7"]={"versions": [{"id": "FIG-0cd8aa4a1129e7d7", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Task-Scheduling- und Timing-Ablaufdiagramm (Gantt-artige Trace-Darstellung auf einer diskreten Tick-Zeitachse für Fixed-Priority Preemptive Scheduling, FPPS).</li>\n<li><strong>Technischer Zweck:</strong> Formale Demonstration der Unzulänglichkeit reiner Deadline-Überwachung (<em>Deadline Monitoring</em>) in prioritätsgesteuerten Echtzeitsystemen.</li>\n<li><strong>Architektur-Einordnung:</strong> AUTOSAR Classic OS (<code>AUTOSAR_SWS_OS</code>, Kapitel <em>Timing Protection</em>). Das Diagramm begründet normativ die Notwendigkeit hardwareunterstützter OS-Schutzmechanismen (<em>Execution Time Protection</em> und <em>Inter-Arrival Time Protection</em>) zur Gewährleistung zeitlicher Kapselung (<em>Temporal Isolation</em> / <em>Freedom from Interference</em> gem. ISO 26262), da reine Fristüberwachungen Fehlallokationen erzeugen und Opfer- statt Verursachertasks sanktionieren.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Scheduling-Entitäten (Tasks mit statischer Prioritätsabstufung $P_A > P_B > P_C$):</strong></li>\n<li><code>Task A</code>: Höchstpriorer Task (präemptiert B und C).</li>\n<li><code>Task B</code>: Task mittlerer Priorität (präemptiert C; wird durch A unterbrochen).</li>\n<li><code>Task C</code>: Niedrigstpriorer Task (Hintergrund-/Niedriglast-Task, Opfer des Kaskadeneffekts).</li>\n<li><strong>Timing-Metriken & Attribute:</strong></li>\n<li><strong>Ausführungszeit / Budget:</strong> Spezifizierte Netto-Laufzeit (graue Blöcke) vs. unzulässige Überziehung / <em>Execution Overrun</em> (rote Blöcke bei Task A und B).</li>\n<li><strong>Aktivierungsintervall / Mindestabstand:</strong> Spezifizierter Mindestabstand (<em>Timeframe</em>) für Task B (erwartete Reaktivierung bei $t = 10$).</li>\n<li><strong>Deadline ($D$):</strong> Spezifische Fristgrenze für den Abschluss einer Instanz (insbes. $D_C = 15$ für Task C).</li>\n<li>*<em>Restlaufzeit (</em>Remaining Execution<em>):</em>* Fehlendes Laufzeitsegment von Task C zum Zeitpunkt des Fristablaufs (grüner Block, $t = 15 \\dots 16$).</li>\n<li><strong>Signalisierung:</strong></li>\n<li>Rotes Ausrufezeichen bei $t = 15$: Erkennung eines <em>Deadline Miss</em> durch ein Deadline-Monitoring-Subsystem.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Chronologischer Trace auf der diskreten Zeitbasis ($t = 0 \\dots 17$ Ticks):</p>\n<ol class=\"fig-list\">\n<li><strong>$t = 1 \\dots 2$ (Task A):</strong> Task A startet und belegt regulär die CPU für 1 Tick.</li>\n<li><strong>$t = 2 \\dots 5$ (Task B – Execution Overrun):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Task B wird aktiv. Die nominelle Ausführungszeit beträgt 2 Ticks ($t = 2 \\dots 4$).</li>\n<li>Task B überzieht die Ausführung um 1 Tick ($t = 4 \\dots 5$, roter Bereich).</li>\n<li><strong>Befund:</strong> Task B erfüllt seine eigene Deadline (<em>meets its deadline</em>); das System registriert keinen Fehler.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>$t = 5 \\dots 7$ (Task A – Execution Overrun):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Task A wird aktiviert und verdrängt die Idle-Phase. Nominelle Ausführungszeit: 1 Tick ($t = 5 \\dots 6$).</li>\n<li>Task A überzieht um 1 Tick ($t = 6 \\dots 7$, roter Bereich).</li>\n<li><strong>Befund:</strong> Task A erfüllt trotz Fehlverhaltens seine Deadline; kein Alarm.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>$t = 7 \\dots 8$ (Task C):</strong> Task C erhält erstmals Rechenzeit (Akkumulierte Laufzeit: 1 von 5 benötigten Ticks).</li>\n<li><strong>$t = 8 \\dots 10$ (Task B – Inter-Arrival-Verletzung):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Task B aktiviert sich unzulässig früh bei $t = 8$ statt frühestens bei $t = 10$ (<em>Rate Violation</em>).</li>\n<li>Task B präemptiert Task C und läuft für 2 Ticks.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>$t = 10 \\dots 11$ (Task A – Reguläre Präemption):</strong> Task A aktiviert sich termingerecht, unterbricht Task B und terminiert nach 1 Tick.</li>\n<li><strong>$t = 11 \\dots 12$ (Task B – Fortsetzung):</strong> Task B nimmt die CPU wieder auf und beendet seinen letzten Tick.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Befund:</strong> Task B hält erneut seine Deadline ein, obgleich zwei Protokollverstöße (Rate Violation und vorangegangener Overrun) vorliegen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>$t = 12 \\dots 15$ (Task C – Fortsetzung):</strong> Task C setzt die Abarbeitung fort und konsumiert 3 weitere Ticks (Gesamtlaufzeit: 4 Ticks).</li>\n<li><strong>$t = 15$ (Fristablauf & Fehlerindikation):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Deadline von Task C läuft ab. Task C hat exakt nach Spezifikation gerechnet, benötigt aber noch 1 Rest-Tick ($t = 15 \\dots 16$, grün).</li>\n<li>Deadline Monitoring schlägt fehl: Task C wird fälschlicherweise als fehlerhaft klassifiziert (<em>Task C misses its deadline</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>$t = 15 \\dots 16$ (Task C – Verspätete Terminierung):</strong> Task C schließt seine Ausführung außerhalb der Frist ab.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>*<em>Fehlerfortpflanzung & Falschallokation (</em>Misattribution<em>):</em>*</li>\n<li>Eine reine Deadline-Überwachung (z. B. via Watchdog Manager, WdgM Deadline Supervision) erkennt Fehler erst ex-post beim schwächsten Glied der Kette (niedrigstpriore Task C), nicht aber am Entstehungsort (höherpriore Tasks A und B).</li>\n<li><strong>Erforderliche OS-Konfiguration nach AUTOSAR OS:</strong></li>\n<li><strong><code>OsTaskExecutionBudget</code>:</strong> Jedem Task/ISR muss ein maximales Netto-Ausführungszeitbudget zugewiesen werden. Bei Überschreiten (hier bei $t = 4$ für B und $t = 6$ für A) greift sofort die Hardware-Timer-Überwachung des OS und ruft den <code>ProtectionHook()</code> auf.</li>\n<li><strong><code>OsTaskTimeFrame</code>:</strong> Parametrierung eines Mindestabstands zwischen zwei Task-Aktivierungen (<em>Inter-Arrival Time Protection</em>). Verhindert das unzulässig frühe Eintreffen von Task B bei $t = 8$ bzw. verzögert die Aktivierung/Abarbeitung bis $t = 10$.</li>\n<li><strong><code>OsTaskResourceLockTime</code> / <code>OsTaskAllInterruptLockTime</code>:</strong> Begrenzung von Blockierzeiten zur Vermeidung verdeckter Priority-Inversion-Effekte.</li>\n<li><strong>Maßnahmen im <code>ProtectionHook()</code>:</strong></li>\n<li>Statt Task C bei $t = 15$ abstürzen zu lassen, muss das OS die Störer bereits bei $t = 4$, $t = 6$ bzw. $t = 8$ abfangen (Aktionen: <code>PRO_TERMINATETASKISR</code>, <code>PRO_TERMINATEAPPL</code> oder Partitionsneustart).</li>\n<li><strong>Safety-Relevanz (ISO 26262):</strong></li>\n<li>Reines Deadline Monitoring genügt in Mixed-Criticality-Systemen (z. B. Task A/B = QM, Task C = ASIL D) <strong>nicht</strong> als Sicherheitsmechanismus für <em>Freedom from Interference in the Time Domain</em>. OS-Timing-Protection ist obligatorisch.</li>\n</ul>"}, {"id": "FIG-e0f133d1eda04ba4", "releases": ["R21-11", "R22-11", "R23-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Task-Scheduling- und Timing-Ablaufdiagramm (Gantt-artige Trace-Darstellung auf einer diskreten Tick-Zeitachse für Fixed-Priority Preemptive Scheduling, FPPS).</li>\n<li><strong>Technischer Zweck:</strong> Formale Demonstration der Unzulänglichkeit reiner Deadline-Überwachung (<em>Deadline Monitoring</em>) in prioritätsgesteuerten Echtzeitsystemen.</li>\n<li><strong>Architektur-Einordnung:</strong> AUTOSAR Classic OS (<code>AUTOSAR_SWS_OS</code>, Kapitel <em>Timing Protection</em>). Das Diagramm begründet normativ die Notwendigkeit hardwareunterstützter OS-Schutzmechanismen (<em>Execution Time Protection</em> und <em>Inter-Arrival Time Protection</em>) zur Gewährleistung zeitlicher Kapselung (<em>Temporal Isolation</em> / <em>Freedom from Interference</em> gem. ISO 26262), da reine Fristüberwachungen Fehlallokationen erzeugen und Opfer- statt Verursachertasks sanktionieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Scheduling-Entitäten (Tasks mit statischer Prioritätsabstufung $P_A > P_B > P_C$):</strong></li>\n<li><code>Task A</code>: Höchstpriorer Task (präemptiert B und C).</li>\n<li><code>Task B</code>: Task mittlerer Priorität (präemptiert C; wird durch A unterbrochen).</li>\n<li><code>Task C</code>: Niedrigstpriorer Task (Hintergrund-/Niedriglast-Task, Opfer des Kaskadeneffekts).</li>\n<li><strong>Timing-Metriken & Attribute:</strong></li>\n<li><strong>Ausführungszeit / Budget:</strong> Spezifizierte Netto-Laufzeit (graue Blöcke) vs. unzulässige Überziehung / <em>Execution Overrun</em> (rote Blöcke bei Task A und B).</li>\n<li><strong>Aktivierungsintervall / Mindestabstand:</strong> Spezifizierter Mindestabstand (<em>Timeframe</em>) für Task B (erwartete Reaktivierung bei $t = 10$).</li>\n<li><strong>Deadline ($D$):</strong> Spezifische Fristgrenze für den Abschluss einer Instanz (insbes. $D_C = 15$ für Task C).</li>\n<li>*<em>Restlaufzeit (</em>Remaining Execution<em>):</em>* Fehlendes Laufzeitsegment von Task C zum Zeitpunkt des Fristablaufs (grüner Block, $t = 15 \\dots 16$).</li>\n<li><strong>Signalisierung:</strong></li>\n<li>Rotes Ausrufezeichen bei $t = 15$: Erkennung eines <em>Deadline Miss</em> durch ein Deadline-Monitoring-Subsystem.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Chronologischer Trace auf der diskreten Zeitbasis ($t = 0 \\dots 17$ Ticks):</p>\n<ol class=\"fig-list\">\n<li><strong>$t = 1 \\dots 2$ (Task A):</strong> Task A startet und belegt regulär die CPU für 1 Tick.</li>\n<li><strong>$t = 2 \\dots 5$ (Task B – Execution Overrun):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Task B wird aktiv. Die nominelle Ausführungszeit beträgt 2 Ticks ($t = 2 \\dots 4$).</li>\n<li>Task B überzieht die Ausführung um 1 Tick ($t = 4 \\dots 5$, roter Bereich).</li>\n<li><strong>Befund:</strong> Task B erfüllt seine eigene Deadline (<em>meets its deadline</em>); das System registriert keinen Fehler.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>$t = 5 \\dots 7$ (Task A – Execution Overrun):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Task A wird aktiviert und verdrängt die Idle-Phase. Nominelle Ausführungszeit: 1 Tick ($t = 5 \\dots 6$).</li>\n<li>Task A überzieht um 1 Tick ($t = 6 \\dots 7$, roter Bereich).</li>\n<li><strong>Befund:</strong> Task A erfüllt trotz Fehlverhaltens seine Deadline; kein Alarm.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>$t = 7 \\dots 8$ (Task C):</strong> Task C erhält erstmals Rechenzeit (Akkumulierte Laufzeit: 1 von 5 benötigten Ticks).</li>\n<li><strong>$t = 8 \\dots 10$ (Task B – Inter-Arrival-Verletzung):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Task B aktiviert sich unzulässig früh bei $t = 8$ statt frühestens bei $t = 10$ (<em>Rate Violation</em>).</li>\n<li>Task B präemptiert Task C und läuft für 2 Ticks.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>$t = 10 \\dots 11$ (Task A – Reguläre Präemption):</strong> Task A aktiviert sich termingerecht, unterbricht Task B und terminiert nach 1 Tick.</li>\n<li><strong>$t = 11 \\dots 12$ (Task B – Fortsetzung):</strong> Task B nimmt die CPU wieder auf und beendet seinen letzten Tick.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Befund:</strong> Task B hält erneut seine Deadline ein, obgleich zwei Protokollverstöße (Rate Violation und vorangegangener Overrun) vorliegen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>$t = 12 \\dots 15$ (Task C – Fortsetzung):</strong> Task C setzt die Abarbeitung fort und konsumiert 3 weitere Ticks (Gesamtlaufzeit: 4 Ticks).</li>\n<li><strong>$t = 15$ (Fristablauf & Fehlerindikation):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Deadline von Task C läuft ab. Task C hat exakt nach Spezifikation gerechnet, benötigt aber noch 1 Rest-Tick ($t = 15 \\dots 16$, grün).</li>\n<li>Deadline Monitoring schlägt fehl: Task C wird fälschlicherweise als fehlerhaft klassifiziert (<em>Task C misses its deadline</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>$t = 15 \\dots 16$ (Task C – Verspätete Terminierung):</strong> Task C schließt seine Ausführung außerhalb der Frist ab.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>*<em>Fehlerfortpflanzung & Falschallokation (</em>Misattribution<em>):</em>*</li>\n<li>Eine reine Deadline-Überwachung (z. B. via Watchdog Manager, WdgM Deadline Supervision) erkennt Fehler erst ex-post beim schwächsten Glied der Kette (niedrigstpriore Task C), nicht aber am Entstehungsort (höherpriore Tasks A und B).</li>\n<li><strong>Erforderliche OS-Konfiguration nach AUTOSAR OS:</strong></li>\n<li><strong><code>OsTaskExecutionBudget</code>:</strong> Jedem Task/ISR muss ein maximales Netto-Ausführungszeitbudget zugewiesen werden. Bei Überschreiten (hier bei $t = 4$ für B und $t = 6$ für A) greift sofort die Hardware-Timer-Überwachung des OS und ruft den <code>ProtectionHook()</code> auf.</li>\n<li><strong><code>OsTaskTimeFrame</code>:</strong> Parametrierung eines Mindestabstands zwischen zwei Task-Aktivierungen (<em>Inter-Arrival Time Protection</em>). Verhindert das unzulässig frühe Eintreffen von Task B bei $t = 8$ bzw. verzögert die Aktivierung/Abarbeitung bis $t = 10$.</li>\n<li><strong><code>OsTaskResourceLockTime</code> / <code>OsTaskAllInterruptLockTime</code>:</strong> Begrenzung von Blockierzeiten zur Vermeidung verdeckter Priority-Inversion-Effekte.</li>\n<li><strong>Maßnahmen im <code>ProtectionHook()</code>:</strong></li>\n<li>Statt Task C bei $t = 15$ abstürzen zu lassen, muss das OS die Störer bereits bei $t = 4$, $t = 6$ bzw. $t = 8$ abfangen (Aktionen: <code>PRO_TERMINATETASKISR</code>, <code>PRO_TERMINATEAPPL</code> oder Partitionsneustart).</li>\n<li><strong>Safety-Relevanz (ISO 26262):</strong></li>\n<li>Reines Deadline Monitoring genügt in Mixed-Criticality-Systemen (z. B. Task A/B = QM, Task C = ASIL D) <strong>nicht</strong> als Sicherheitsmechanismus für <em>Freedom from Interference in the Time Domain</em>. OS-Timing-Protection ist obligatorisch.</li>\n</ul>"}, {"id": "FIG-7c688a9ddd4eac14", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Task-Scheduling- und Timing-Ablaufdiagramm (Gantt-artige Trace-Darstellung auf einer diskreten Tick-Zeitachse für Fixed-Priority Preemptive Scheduling, FPPS).</li>\n<li><strong>Technischer Zweck:</strong> Formale Demonstration der Unzulänglichkeit reiner Deadline-Überwachung (<em>Deadline Monitoring</em>) in prioritätsgesteuerten Echtzeitsystemen.</li>\n<li><strong>Architektur-Einordnung:</strong> AUTOSAR Classic OS (<code>AUTOSAR_SWS_OS</code>, Kapitel <em>Timing Protection</em>). Das Diagramm begründet normativ die Notwendigkeit hardwareunterstützter OS-Schutzmechanismen (<em>Execution Time Protection</em> und <em>Inter-Arrival Time Protection</em>) zur Gewährleistung zeitlicher Kapselung (<em>Temporal Isolation</em> / <em>Freedom from Interference</em> gem. ISO 26262), da reine Fristüberwachungen Fehlallokationen erzeugen und Opfer- statt Verursachertasks sanktionieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Scheduling-Entitäten (Tasks mit statischer Prioritätsabstufung $P_A > P_B > P_C$):</strong></li>\n<li><code>Task A</code>: Höchstpriorer Task (präemptiert B und C).</li>\n<li><code>Task B</code>: Task mittlerer Priorität (präemptiert C; wird durch A unterbrochen).</li>\n<li><code>Task C</code>: Niedrigstpriorer Task (Hintergrund-/Niedriglast-Task, Opfer des Kaskadeneffekts).</li>\n<li><strong>Timing-Metriken & Attribute:</strong></li>\n<li><strong>Ausführungszeit / Budget:</strong> Spezifizierte Netto-Laufzeit (graue Blöcke) vs. unzulässige Überziehung / <em>Execution Overrun</em> (rote Blöcke bei Task A und B).</li>\n<li><strong>Aktivierungsintervall / Mindestabstand:</strong> Spezifizierter Mindestabstand (<em>Timeframe</em>) für Task B (erwartete Reaktivierung bei $t = 10$).</li>\n<li><strong>Deadline ($D$):</strong> Spezifische Fristgrenze für den Abschluss einer Instanz (insbes. $D_C = 15$ für Task C).</li>\n<li>*<em>Restlaufzeit (</em>Remaining Execution<em>):</em>* Fehlendes Laufzeitsegment von Task C zum Zeitpunkt des Fristablaufs (grüner Block, $t = 15 \\dots 16$).</li>\n<li><strong>Signalisierung:</strong></li>\n<li>Rotes Ausrufezeichen bei $t = 15$: Erkennung eines <em>Deadline Miss</em> durch ein Deadline-Monitoring-Subsystem.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Chronologischer Trace auf der diskreten Zeitbasis ($t = 0 \\dots 17$ Ticks):</p>\n<ol class=\"fig-list\">\n<li><strong>$t = 1 \\dots 2$ (Task A):</strong> Task A startet und belegt regulär die CPU für 1 Tick.</li>\n<li><strong>$t = 2 \\dots 5$ (Task B – Execution Overrun):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Task B wird aktiv. Die nominelle Ausführungszeit beträgt 2 Ticks ($t = 2 \\dots 4$).</li>\n<li>Task B überzieht die Ausführung um 1 Tick ($t = 4 \\dots 5$, roter Bereich).</li>\n<li><strong>Befund:</strong> Task B erfüllt seine eigene Deadline (<em>meets its deadline</em>); das System registriert keinen Fehler.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>$t = 5 \\dots 7$ (Task A – Execution Overrun):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Task A wird aktiviert und verdrängt die Idle-Phase. Nominelle Ausführungszeit: 1 Tick ($t = 5 \\dots 6$).</li>\n<li>Task A überzieht um 1 Tick ($t = 6 \\dots 7$, roter Bereich).</li>\n<li><strong>Befund:</strong> Task A erfüllt trotz Fehlverhaltens seine Deadline; kein Alarm.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>$t = 7 \\dots 8$ (Task C):</strong> Task C erhält erstmals Rechenzeit (Akkumulierte Laufzeit: 1 von 5 benötigten Ticks).</li>\n<li><strong>$t = 8 \\dots 10$ (Task B – Inter-Arrival-Verletzung):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Task B aktiviert sich unzulässig früh bei $t = 8$ statt frühestens bei $t = 10$ (<em>Rate Violation</em>).</li>\n<li>Task B präemptiert Task C und läuft für 2 Ticks.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>$t = 10 \\dots 11$ (Task A – Reguläre Präemption):</strong> Task A aktiviert sich termingerecht, unterbricht Task B und terminiert nach 1 Tick.</li>\n<li><strong>$t = 11 \\dots 12$ (Task B – Fortsetzung):</strong> Task B nimmt die CPU wieder auf und beendet seinen letzten Tick.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Befund:</strong> Task B hält erneut seine Deadline ein, obgleich zwei Protokollverstöße (Rate Violation und vorangegangener Overrun) vorliegen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>$t = 12 \\dots 15$ (Task C – Fortsetzung):</strong> Task C setzt die Abarbeitung fort und konsumiert 3 weitere Ticks (Gesamtlaufzeit: 4 Ticks).</li>\n<li><strong>$t = 15$ (Fristablauf & Fehlerindikation):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Deadline von Task C läuft ab. Task C hat exakt nach Spezifikation gerechnet, benötigt aber noch 1 Rest-Tick ($t = 15 \\dots 16$, grün).</li>\n<li>Deadline Monitoring schlägt fehl: Task C wird fälschlicherweise als fehlerhaft klassifiziert (<em>Task C misses its deadline</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>$t = 15 \\dots 16$ (Task C – Verspätete Terminierung):</strong> Task C schließt seine Ausführung außerhalb der Frist ab.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>*<em>Fehlerfortpflanzung & Falschallokation (</em>Misattribution<em>):</em>*</li>\n<li>Eine reine Deadline-Überwachung (z. B. via Watchdog Manager, WdgM Deadline Supervision) erkennt Fehler erst ex-post beim schwächsten Glied der Kette (niedrigstpriore Task C), nicht aber am Entstehungsort (höherpriore Tasks A und B).</li>\n<li><strong>Erforderliche OS-Konfiguration nach AUTOSAR OS:</strong></li>\n<li><strong><code>OsTaskExecutionBudget</code>:</strong> Jedem Task/ISR muss ein maximales Netto-Ausführungszeitbudget zugewiesen werden. Bei Überschreiten (hier bei $t = 4$ für B und $t = 6$ für A) greift sofort die Hardware-Timer-Überwachung des OS und ruft den <code>ProtectionHook()</code> auf.</li>\n<li><strong><code>OsTaskTimeFrame</code>:</strong> Parametrierung eines Mindestabstands zwischen zwei Task-Aktivierungen (<em>Inter-Arrival Time Protection</em>). Verhindert das unzulässig frühe Eintreffen von Task B bei $t = 8$ bzw. verzögert die Aktivierung/Abarbeitung bis $t = 10$.</li>\n<li><strong><code>OsTaskResourceLockTime</code> / <code>OsTaskAllInterruptLockTime</code>:</strong> Begrenzung von Blockierzeiten zur Vermeidung verdeckter Priority-Inversion-Effekte.</li>\n<li><strong>Maßnahmen im <code>ProtectionHook()</code>:</strong></li>\n<li>Statt Task C bei $t = 15$ abstürzen zu lassen, muss das OS die Störer bereits bei $t = 4$, $t = 6$ bzw. $t = 8$ abfangen (Aktionen: <code>PRO_TERMINATETASKISR</code>, <code>PRO_TERMINATEAPPL</code> oder Partitionsneustart).</li>\n<li><strong>Safety-Relevanz (ISO 26262):</strong></li>\n<li>Reines Deadline Monitoring genügt in Mixed-Criticality-Systemen (z. B. Task A/B = QM, Task C = ASIL D) <strong>nicht</strong> als Sicherheitsmechanismus für <em>Freedom from Interference in the Time Domain</em>. OS-Timing-Protection ist obligatorisch.</li>\n</ul>"}], "trans": [{"from": "FIG-0cd8aa4a1129e7d7", "to": "FIG-e0f133d1eda04ba4", "fr": "R4.2.2", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e0f133d1eda04ba4", "to": "FIG-7c688a9ddd4eac14", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7c688a9ddd4eac14", "to": "FIG-e0f133d1eda04ba4", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
